---@param handTF_ UnityEngine.Transform 
---@param isInitShow_ boolean
function IdolLive3D_UIHand:__init( handTF_, isInitShow_ )
    self.handTF = handTF_
    ---
    self:Show(isInitShow_ == true)

    self:SetCamera( IdolLive3D_Utils.GetMainCamera() )

    self.rootCanvasCoordinateMatrix = DreamSpaceUtils.RefreshRootCanvasCoordinateMatrix( self.handTF );
end




-- 需手动调用 Delete()
function IdolLive3D_UIHand:__delete()
end


----------------------------------------------------------


function IdolLive3D_UIHand:SetCamera( camera_ )
    self.camera = camera_
end


function IdolLive3D_UIHand:SetPos( posWS_ )
    -- Vector2
    local newAnchoredPosition = DreamSpaceUtils.CalculateAnchoredPosition( self.camera, posWS_, 0 )
    -- 准确计算 ui元素的 world-space 3d position:
    local pos = DreamSpaceUtils.AnchoredPosition_To_PosWS( newAnchoredPosition, self.rootCanvasCoordinateMatrix );
    self.handTF.position = pos
end



---@param isShow_ boolean
function IdolLive3D_UIHand:Show( isShow_ )
    KTool.SetActive( self.handTF.gameObject, isShow_ )
end



function IdolLive3D_UIHand:PlayRemind()
    CfUtils.PlayAnimation( self.handTF, animName_Remind ) -- loop
end


function IdolLive3D_UIHand:PlayTouch()
    CfUtils.PlayAnimation( self.handTF, animName_Touch ) -- once
end







return IdolLive3D_UIHand
